$ErrorActionPreference='Stop'
$root='C:\Users\yoray\Projects\Yor-World-Local-Corrections'
$base=Join-Path $root 'deliveries\production-environment\revisions\local-corrections-r1'
$assetPath=Join-Path $root 'app\public\asset-manifest.json'
$deliveryPath=Join-Path $base 'manifest.json'
