foreach($p in @($assetPath,$deliveryPath,$recordPath,$receiptPath,$lodPath)){if(!(Test-Path -LiteralPath $p)){throw "Missing attempt-09 evidence prerequisite $p"}}
foreach($p in @($provPath,$verifyPath,$reportPath)){if(Test-Path -LiteralPath $p){throw "Refusing to overwrite $p"}}
$asset=Get-Content -LiteralPath $assetPath -Raw|ConvertFrom-Json
$record=Get-Content -LiteralPath $recordPath -Raw|ConvertFrom-Json
$lod=Get-Content -LiteralPath $lodPath -Raw|ConvertFrom-Json
$receipt=Get-Content -LiteralPath $receiptPath -Raw|ConvertFrom-Json
$sourcePaths=@('deliveries/production-environment/revisions/local-corrections-r1/source/prepare-authoring.py','deliveries/production-environment/revisions/local-corrections-r1/source/art_refinements.py','deliveries/production-environment/revisions/local-corrections-r1/source/environment/build-environment.py','deliveries/production-environment/revisions/local-corrections-r1/source/environment/generate-carpet-texture.py','deliveries/production-environment/revisions/local-corrections-r1/source/environment/textures/floor-carpet-microtexture.png','deliveries/production-environment/revisions/local-corrections-r1/source/resident-fixture/build-resident-production.py')
$inputs=foreach($rel in $sourcePaths){$p=Join-Path $root $rel.Replace('/','\');$f=Get-Item -LiteralPath $p;[pscustomobject]@{path=$rel;bytes=[int64]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
$assetChecks=foreach($out in $record.outputs){$g=@($asset.groups|Where-Object {$_.id -eq $out.id})|Select-Object -First 1;$p=Join-Path $root ('app/public'+$out.url.Replace('/','\'));$h=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant();[pscustomobject]@{id=$out.id;url=$out.url;provenanceId=$g.provenanceId;sha256Manifest=$g.sha256;sha256Disk=$h;bytes=$g.bytes;triangles=$g.triangles;materials=$g.materials;estimatedGpuBytes=$g.estimatedGpuBytes;approved=$g.approved;status=$g.status;hashMatch=($h -eq $g.sha256 -and $h -eq $out.sha256)}}
$fixturePath=Join-Path $root 'app\public\models\world-art-local-corrections-20261009-r1\fixture-production.c7ed99092cfc2d71470065099cec2a0d1dac565e149521dff28c588677cbc3a5.glb'
$fixtureHash=(Get-FileHash -LiteralPath $fixturePath -Algorithm SHA256).Hash.ToLowerInvariant()
$baseProvHash=(Get-FileHash -LiteralPath (Join-Path $base 'provenance.json') -Algorithm SHA256).Hash.ToLowerInvariant()
$prov=[pscustomobject]@{id='world-art-local-corrections-20261009-r1-continuation-20261011-attempt-09';revision=$asset.revision;executor='local Codex /root/art_assets (resumed art lane)';generatedAt=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ss.fffZ');status='candidate only; independent visual/provenance review and parent admission pending';parentProvenance=[pscustomobject]@{path='deliveries/production-environment/revisions/local-corrections-r1/provenance.json';sha256=$baseProvHash};sourceFingerprints=@($inputs);continuationRecord=[pscustomobject]@{path='deliveries/production-environment/revisions/local-corrections-r1/evidence/continuation-record-attempt-09.json';sha256=(Get-FileHash -LiteralPath $recordPath -Algorithm SHA256).Hash.ToLowerInvariant()};mobileLodComparison=[pscustomobject]@{path='deliveries/production-environment/revisions/local-corrections-r1/evidence/mobile-lod-comparison-attempt-09.json';sha256=(Get-FileHash -LiteralPath $lodPath -Algorithm SHA256).Hash.ToLowerInvariant();requestedRatio=$lod.requestedCollapseRatio;eligibleMeshCount=$lod.aggregate.eligibleMeshCount;eligibleActualRatio=$lod.aggregate.eligibleAggregateActualRatio;protectedMeshes=$lod.aggregate.protectedBoundsMeshes};assetManifest=[pscustomobject]@{path='app/public/asset-manifest.json';sha256=(Get-FileHash -LiteralPath $assetPath -Algorithm SHA256).Hash.ToLowerInvariant()};assets=@($assetChecks);unchangedFixture=[pscustomobject]@{path='app/public/models/world-art-local-corrections-20261009-r1/fixture-production.c7ed99092cfc2d71470065099cec2a0d1dac565e149521dff28c588677cbc3a5.glb';sha256=$fixtureHash;approved=$false;status='candidate; unchanged'};build=[pscustomobject]@{blender='5.2.2 LTS';attempt='build-attempt-09';log='deliveries/production-environment/revisions/local-corrections-r1/evidence/environment-execution-attempt-09.log';exitCode=0};exportValidation=[pscustomobject]@{gltfValidator=$lod.validation.gltfValidatorVersion;fullErrors=$lod.validation.fullValidatorErrors;fullWarnings=$lod.validation.fullValidatorWarnings;mobileErrors=$lod.validation.mobileValidatorErrors;mobileWarnings=$lod.validation.mobileValidatorWarnings;fullTransformChecks=$lod.validation.fullTransformChecks;fullTransformFailures=$lod.validation.fullTransformFailures;mobileTransformChecks=$lod.validation.mobileTransformChecks;mobileTransformFailures=$lod.validation.mobileTransformFailures};visual=[pscustomobject]@{capture='NOT RUN';reason='Parent required a coordinated freeze before any shared browser capture';olderCaptureDirectory='deliveries/production-environment/revisions/local-corrections-r1/evidence/browser-art-attempt-02';olderManifestSha256='2f846c6ddf5c0a1cb1f85b31c4dbf27a4400d8aca4f0f6009374d3f38e401027';independentReview='pending'};unpublishedAttempts=@([pscustomobject]@{attempt='build-attempt-07';status='preserved, not published';reason='strict bounds proof failed on desk_modesty_panel and monstera_leaf_1..4'},[pscustomobject]@{attempt='build-attempt-08';status='preserved, not published';reason='strict checks passed but 0.72 ratio did not meet source contract 0.55'})}
[IO.File]::WriteAllText($provPath,(ConvertTo-Json -InputObject $prov -Depth 40),[Text.UTF8Encoding]::new($false))
$verify=[pscustomobject]@{generatedAt=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ss.fffZ');status=if(@($assetChecks|Where-Object {-not $_.hashMatch}).Count -eq 0){'PASS'}else{'FAIL'};assetManifest=[pscustomobject]@{path='app/public/asset-manifest.json';sha256=(Get-FileHash -LiteralPath $assetPath -Algorithm SHA256).Hash.ToLowerInvariant();revision=$asset.revision};deliveryManifest=[pscustomobject]@{path='deliveries/production-environment/revisions/local-corrections-r1/manifest.json';sha256=(Get-FileHash -LiteralPath $deliveryPath -Algorithm SHA256).Hash.ToLowerInvariant()};outputs=@($assetChecks);allChangedOutputsUnapproved=@($assetChecks|Where-Object {$_.approved -ne $false -or $_.status -ne 'candidate'}).Count -eq 0;fixtureSha256=$fixtureHash;lodComparisonSha256=(Get-FileHash -LiteralPath $lodPath -Algorithm SHA256).Hash.ToLowerInvariant();provenancePath='deliveries/production-environment/revisions/local-corrections-r1/provenance-continuation-attempt-09.json'}
[IO.File]::WriteAllText($verifyPath,(ConvertTo-Json -InputObject $verify -Depth 30),[Text.UTF8Encoding]::new($false))
$report=@('# Local art correction continuation, attempt 09 (2026-10-11)','','This is a candidate-only worker-2 continuation. Attempts 06–08 and their sources/receipts remain preserved. No candidate is independently visually approved or parent-admitted.','','## Art updates','','Source changes refine wall/desk/plant colors, floor material, hex panel geometry and emission, desk/shelf bevels and drawer fronts, split monstera leaf silhouettes, and shelf ivy. The carpet texture is generated by `source/environment/generate-carpet-texture.py`. The Blender source also now applies a real 0.55 COLLAPSE Decimate modifier to eligible mobile-tier meshes; five meshes are explicitly preserved where attempt-07 bounds checks showed decimation exceeds authored bounds.','','## Build and export evidence','','Blender 5.2.2 LTS attempt-09 completed with exit 0; raw log: `evidence/environment-execution-attempt-09.log`. The exact-source inspector receipt is `evidence/export-inspection-resumed-20261011-attempt-04.json`: six GLBs each have zero glTF errors/warnings. Full/mobile world exports each pass 246 authored transform/bounds checks; group-A passes 129, group-B 84, on-demand 33, fixture 67. These structural checks do not establish visual acceptance.','','The mobile LOD comparison is `evidence/mobile-lod-comparison-attempt-09.json`. The 33 decimated meshes total 8,136 source triangles and 4,436 output triangles, actual aggregate 0.5452 against requested 0.55. Five unchanged meshes are `desk_modesty_panel` and `monstera_leaf_1` through `monstera_leaf_4`. Across the full room, mobile reduces triangles from 13,732 to 10,032 (3,700 / 26.94%) and GLB bytes from 1,342,960 to 1,237,852 (105,108 / 7.83%). The full and mobile groups each retain 39 materials.','','Fixture clearance record `evidence/fixture-attempt-03/blender-checks.json` has zero desk-interior hits and sole height 0 in all eight clips; visitor-turn and greeting hand clearances are 0.16 m and 0.3312 m. Its measurement file contains 1,040 samples at 60 Hz. The fixture bytes remain unchanged and candidate-only.','','Transform anchors in the full GLB: group root and desk at origin; desk top (0, 0.725, -1.15) m; chair root (0.3, 0, -0.36) m; door hinge (-1.65, 0, 1.8) m with `door_leaf` as child; painting pivot (2.08, 1.75, -0.4) m. Runtime mapping/action behavior is owned by other lanes and was not edited here.','','## Current candidate manifest','','`app/public/asset-manifest.json` current SHA-256 is recorded in `evidence/publication-verification-attempt-09.json`. Five changed files are full SHA-256 named under `app/public/models/world-art-local-corrections-20261009-r1/`; no historical public file was overwritten. All five stay `approved: false`, `status: candidate`.','','## Visual evidence and remaining review','','The available six-viewport browser set remains `evidence/browser-art-attempt-02/` and is tied to its older manifest SHA-256 `2f846c6ddf5c0a1cb1f85b31c4dbf27a4400d8aca4f0f6009374d3f38e401027`; it is not evidence for attempt-09. Parent review of those screenshots reported pale washed-out hex panels, a sparse/blocky scene, and excessive ceiling/floor in mobile framing. Attempt-09 browser captures are NOT RUN because the parent froze shared browser/build work pending coordination. The runtime lane reports its camera framing is stable and is waiting for the final manifest binding. Independent visual/provenance review and parent admission remain pending.') -join [Environment]::NewLine
[IO.File]::WriteAllText($reportPath,$report,[Text.UTF8Encoding]::new($false))
[pscustomobject]@{provenanceSha256=(Get-FileHash -LiteralPath $provPath -Algorithm SHA256).Hash.ToLowerInvariant();verificationSha256=(Get-FileHash -LiteralPath $verifyPath -Algorithm SHA256).Hash.ToLowerInvariant();reportSha256=(Get-FileHash -LiteralPath $reportPath -Algorithm SHA256).Hash.ToLowerInvariant();manifestSha256=(Get-FileHash -LiteralPath $assetPath -Algorithm SHA256).Hash.ToLowerInvariant();verificationStatus=$verify.status;allChangedOutputsUnapproved=$verify.allChangedOutputsUnapproved}|ConvertTo-Json -Compress